// ==UserScript==
// @name         Relatório Projudi - Processos Arquivados com Saldo
// @namespace    https://projudi2.tjpr.jus.br/
// @version      1.0
// @description  Na tela do Relatório Dinâmico "Processos Arquivados com saldo (depósito eletrônico)" do Projudi, extrai o CSV do relatório e gera um PDF com resumo (total de processos/saldo total/saldo médio) e a tabela discriminada.
// @author       rcpleme2
// @match        https://projudi2.tjpr.jus.br/projudi/*
// @updateURL    https://raw.githubusercontent.com/rcpleme2/tampermonkey_relatorio_projudi/main/relatorio_arquivados_saldo.user.js
// @downloadURL  https://raw.githubusercontent.com/rcpleme2/tampermonkey_relatorio_projudi/main/relatorio_arquivados_saldo.user.js
// @require      https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js
// @require      https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js
// @grant        GM_xmlhttpRequest
// @connect      projudi2.tjpr.jus.br
// ==/UserScript==

// Userscript INDEPENDENTE do relatorio_projudi.user.js principal (pedido do usuário:
// desenvolver este relatório desacoplado, sem entrar no pipeline de automação/capa
// unificada do script grande). Cobre só a tela do Relatório Dinâmico "Processos
// Arquivados com saldo (depósito eletrônico)" (Relatórios/Estatísticas > Relatórios
// Dinâmicos > o link desse relatório — navegação manual, como qualquer outro relatório
// dinâmico do Projudi): ao chegar nessa tela, injeta um botão que extrai o CSV e gera o
// PDF, sem precisar clicar em "Gerar Relatório" de verdade.
//
// POR QUE NÃO CLICAR NO BOTÃO NATIVO "GERAR RELATÓRIO": o formulário tem
// target="relatorio" e a tela não tem nenhum <iframe name="relatorio"> — clicar de
// verdade abriria uma aba/janela NOVA pra exibir/baixar o CSV. Como esse clique
// aconteceria via automação (sem gesto real do usuário), o navegador tende a bloquear
// essa nova aba/janela como pop-up — e mesmo quando não bloqueia, não há como o
// Tampermonkey ler de volta um arquivo baixado nativamente. A alternativa usada aqui é
// pedir os MESMOS dados do formulário (tamanhoFonte/formato padrão da tela,
// tipoExportacao forçado pra CSV) via GM_xmlhttpRequest direto pra form.action, na MESMA
// aba, e ler a resposta como texto.
(function () {
    'use strict';

    // ── Paleta e helpers visuais (mesmo estilo do relatorio_projudi.user.js principal,
    // pra manter a identidade visual do PDF — ver COR/desenharCard/tituloSecao/
    // desenharRodape lá) ─────────────────────────────────────────────────────────────
    const COR = {
        tinta:    [26, 26, 26],
        tintaSec: [82, 81, 78],
        muted:    [130, 128, 122],
        grade:    [222, 221, 214],
        cartao:   [244, 244, 241],
        azul:     [58, 90, 125],
        aqua:     [82, 116, 103],
        ambar:    [156, 116, 46],
        vermelho: [146, 58, 58],
        azulTint: [238, 242, 246],
    };
    const DIA_MS = 86400000;

    function parseDataBR(str) {
        const m = /(\d{2})\/(\d{2})\/(\d{4})/.exec(str || '');
        if (!m) return null;
        return new Date(+m[3], +m[2] - 1, +m[1]).getTime();
    }

    function tituloSecao(doc, x, y, w, texto) {
        doc.setFont('PublicSans', 'bold'); doc.setFontSize(10); doc.setTextColor(...COR.tinta);
        doc.text(texto, x, y);
        doc.setDrawColor(...COR.azul); doc.setLineWidth(0.7);
        doc.line(x, y + 1.6, x + Math.min(w, doc.getTextWidth(texto) + 2), y + 1.6);
    }

    function textoTruncadoParaLargura(doc, texto, larguraMax) {
        const s = String(texto);
        if (doc.getTextWidth(s) <= larguraMax) return s;
        let t = s;
        while (t.length > 1 && doc.getTextWidth(t + '…') > larguraMax) t = t.slice(0, -1);
        return t + '…';
    }

    function desenharCard(doc, x, y, w, h, titulo, valor, subs, acento) {
        acento = acento || COR.azul;
        doc.setDrawColor(...COR.grade); doc.setFillColor(...COR.cartao); doc.setLineWidth(0.2);
        doc.roundedRect(x, y, w, h, 2, 2, 'FD');
        doc.setFillColor(...acento);
        doc.roundedRect(x, y, 1.8, h, 0.9, 0.9, 'F');
        subs = (subs || []).filter(Boolean);

        const cx = x + w / 2;
        const blocoH = 4 + 8 + subs.length * 4.2;
        let yy = y + (h - blocoH) / 2 + 4;
        doc.setFont('PublicSans', 'bold'); doc.setFontSize(7.5); doc.setTextColor(...COR.muted);
        doc.text(String(titulo).toUpperCase(), cx, yy, { align: 'center' }); yy += 7;
        doc.setFont('PublicSans', 'bold');
        const valorTexto = String(valor);
        const TAMANHOS = [15, 13, 11, 10, 9];
        let fonteValor = TAMANHOS[TAMANHOS.length - 1];
        for (const tam of TAMANHOS) {
            doc.setFontSize(tam);
            if (doc.getTextWidth(valorTexto) <= w - 10) { fonteValor = tam; break; }
        }
        doc.setFontSize(fonteValor); doc.setTextColor(...COR.tinta);
        doc.text(textoTruncadoParaLargura(doc, valorTexto, w - 10), cx, yy, { align: 'center' }); yy += 5.5;
        doc.setFont('PublicSans', 'normal'); doc.setFontSize(8); doc.setTextColor(...COR.tintaSec);
        subs.forEach(s => { doc.text(doc.splitTextToSize(String(s), w - 10)[0], cx, yy, { align: 'center' }); yy += 4.2; });
    }

    function desenharRodape(doc, titulo, quando, pw, ph, m) {
        doc.setFont('PublicSans', 'normal'); doc.setFontSize(8); doc.setTextColor(...COR.muted);
        doc.text(`${titulo}  •  Página ${doc.internal.getNumberOfPages()}`, m, ph - 6);
        doc.text(quando, pw - m, ph - 6, { align: 'right' });
    }

    // ── CSV: ponto-e-vírgula, campos entre aspas, windows-1252 (mesmo encoding do resto
    // do Projudi) — colunas fixas: Processo; Dt Arquivamento; Conta Judicial; Dt Última
    // Atualização CEF; Saldo ──────────────────────────────────────────────────────────
    function mascararProcesso(digitos) {
        const d = String(digitos || '').replace(/\D/g, '');
        if (d.length !== 20) return digitos;
        return `${d.slice(0, 7)}-${d.slice(7, 9)}.${d.slice(9, 13)}.${d.slice(13, 14)}.${d.slice(14, 16)}.${d.slice(16, 20)}`;
    }

    function parseSaldoBR(str) {
        const limpo = String(str || '').replace(/[^\d,.-]/g, '').trim();
        if (!limpo) return 0;
        return parseFloat(limpo.replace(/\./g, '').replace(',', '.')) || 0;
    }

    function fmtBRL(v) {
        return (v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    }

    function parseLinhaCSV(linha) {
        return linha.split(';').map(c => c.trim().replace(/^"|"$/g, ''));
    }

    function parseCSV(texto) {
        const linhas = String(texto || '').split('\n').map(l => l.replace(/\r$/, '')).filter(l => l.trim().length);
        const [, ...corpo] = linhas; // descarta o cabeçalho
        return corpo.map(linha => {
            const [processoCru, dtArquivamento, contaJudicial, dtAtualizacaoCEF, saldoStr] = parseLinhaCSV(linha);
            return {
                processo: mascararProcesso(processoCru),
                dtArquivamento, contaJudicial, dtAtualizacaoCEF, saldoStr,
                saldo: parseSaldoBR(saldoStr),
            };
        });
    }

    // ── Detecção da tela e coleta via GM_xmlhttpRequest ─────────────────────────────
    // GM_xmlhttpRequest (em vez de fetch()) evita depender de como o sandbox do
    // Tampermonkey expõe fetch/cookies nesta instalação — é a forma documentada e mais
    // robusta de fazer uma requisição autenticada (mesma sessão) a partir de um
    // userscript.
    function formularioArquivadosSaldo() {
        const form = document.getElementById('relatorioForm');
        if (!form) return null;
        const labels = form.querySelectorAll('td.label');
        for (const label of labels) {
            if (!/^nome:?$/i.test(label.textContent.trim())) continue;
            const valorTd = label.nextElementSibling;
            if (valorTd && /processos\s+arquivados\s+com\s+saldo/i.test(valorTd.textContent)) return form;
        }
        return null;
    }

    function coletarCSV(urlAction) {
        return new Promise((resolve, reject) => {
            const corpo = new URLSearchParams({ tamanhoFonte: '10', formato: 'R', tipoExportacao: 'CSV' }).toString();
            GM_xmlhttpRequest({
                method: 'POST',
                url: urlAction,
                data: corpo,
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                responseType: 'arraybuffer',
                onload: (resp) => {
                    if (resp.status < 200 || resp.status >= 300) {
                        reject(new Error(`HTTP ${resp.status} ao solicitar o relatório`));
                        return;
                    }
                    let texto;
                    try {
                        texto = new TextDecoder('windows-1252').decode(resp.response);
                    } catch (e) {
                        reject(new Error('Não foi possível decodificar a resposta como texto: ' + e.message));
                        return;
                    }
                    if (!/^"?Processo"?\s*;/i.test(texto.trim())) {
                        reject(new Error('A resposta não parece o CSV esperado (cabeçalho "Processo;..." ausente) — sessão pode ter expirado.'));
                        return;
                    }
                    resolve(texto);
                },
                onerror: () => reject(new Error('Falha de rede ao solicitar o relatório (GM_xmlhttpRequest onerror).')),
                ontimeout: () => reject(new Error('Tempo esgotado ao solicitar o relatório.')),
            });
        });
    }
    const FONTE_PUBLIC_SANS_REGULAR = '';
    const FONTE_PUBLIC_SANS_BOLD = '';
    const FONTE_PUBLIC_SANS_ITALIC = '';

    // ── Geração do PDF ───────────────────────────────────────────────────────────
    function novoDocPDF() {
        const ctor = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
        if (!ctor) throw new Error('biblioteca jsPDF não carregada');
        const doc = new ctor({ orientation: 'portrait', unit: 'mm', format: 'a4', compress: true });
        if (typeof doc.autoTable !== 'function') throw new Error('plugin autoTable não carregado');
        doc.addFileToVFS('PublicSans-Regular.ttf', FONTE_PUBLIC_SANS_REGULAR);
        doc.addFont('PublicSans-Regular.ttf', 'PublicSans', 'normal');
        doc.addFileToVFS('PublicSans-Bold.ttf', FONTE_PUBLIC_SANS_BOLD);
        doc.addFont('PublicSans-Bold.ttf', 'PublicSans', 'bold');
        doc.addFileToVFS('PublicSans-Italic.ttf', FONTE_PUBLIC_SANS_ITALIC);
        doc.addFont('PublicSans-Italic.ttf', 'PublicSans', 'italic');
        doc.setFont('PublicSans', 'normal');
        return doc;
    }

    const TITULO = 'Processos Arquivados com Saldo (Depósito Eletrônico)';

    function montarResumo(doc, dados) {
        const agora = new Date();
        const pw = doc.internal.pageSize.getWidth();
        const ph = doc.internal.pageSize.getHeight();
        const m = 12;
        const uw = pw - 2 * m;
        const carimbo = `${agora.toLocaleDateString('pt-BR')} ${agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`;
        const gap = 6;
        const r = dados || [];

        doc.setFont('PublicSans', 'bold'); doc.setFontSize(16); doc.setTextColor(...COR.tinta);
        doc.text(TITULO, m, m + 2);
        doc.setFont('PublicSans', 'normal'); doc.setFontSize(9); doc.setTextColor(...COR.tintaSec);
        doc.text(`Extraído em ${carimbo}  •  ${r.length} processo(s)`, m, m + 9);
        const yLinha = m + 12;
        doc.setDrawColor(...COR.azul); doc.setLineWidth(0.5); doc.line(m, yLinha, pw - m, yLinha);

        const saldoTotal = r.reduce((s, d) => s + (d.saldo || 0), 0);
        const saldoMedio = r.length ? saldoTotal / r.length : 0;

        const kY = yLinha + 6;
        const kpis = [
            { titulo: 'Total de Processos', valor: String(r.length), acento: COR.azul },
            { titulo: 'Saldo Total', valor: fmtBRL(saldoTotal), acento: COR.aqua },
            { titulo: 'Saldo Médio por Processo', valor: fmtBRL(saldoMedio), acento: COR.ambar },
        ];
        const kW = (uw - (kpis.length - 1) * gap) / kpis.length;
        kpis.forEach((k, i) => desenharCard(doc, m + i * (kW + gap), kY, kW, 28, k.titulo, k.valor, [], k.acento));

        const aY = kY + 28 + gap;
        let maisAntigo = null;
        r.forEach(d => {
            const ts = parseDataBR(d.dtArquivamento);
            if (ts == null) return;
            if (!maisAntigo || ts < maisAntigo.ts) maisAntigo = { ts, d };
        });
        let valAntigo = '—', subsAntigo = ['Data não disponível'];
        if (maisAntigo) {
            const dias = Math.max(0, Math.floor((Date.now() - maisAntigo.ts) / DIA_MS));
            valAntigo = `${maisAntigo.d.dtArquivamento}  (${dias} dias arquivado)`;
            subsAntigo = [`Processo ${maisAntigo.d.processo}`, `Saldo: ${fmtBRL(maisAntigo.d.saldo)}`];
        }
        desenharCard(doc, m, aY, uw, 28, 'Arquivamento Mais Antigo Com Saldo', valAntigo, subsAntigo, COR.vermelho);

        desenharRodape(doc, TITULO, carimbo, pw, ph, m);
        return aY + 28 + gap;
    }

    function montarTabela(doc, dados) {
        doc.addPage();
        const agora = new Date();
        const pw = doc.internal.pageSize.getWidth();
        const ph = doc.internal.pageSize.getHeight();
        const m = 12;
        const uw = pw - 2 * m;
        const carimbo = `${agora.toLocaleDateString('pt-BR')} ${agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`;
        const r = dados || [];

        tituloSecao(doc, m, m + 4, uw, `Tabela discriminada — ${TITULO} (${r.length} processo(s))`);
        const tabInicioY = m + 10;

        const colunas = [
            { header: 'Processo', width: 26, get: d => d.processo },
            { header: 'Dt Arquivamento', width: 12, get: d => d.dtArquivamento },
            { header: 'Conta Judicial', width: 15, get: d => d.contaJudicial },
            { header: 'Dt Últ. Atualização CEF', width: 13, get: d => d.dtAtualizacaoCEF },
            { header: 'Saldo', width: 12, get: d => fmtBRL(d.saldo) },
        ];
        const somaLarguras = colunas.reduce((s, c) => s + c.width, 0);
        const fatorLargura = uw / somaLarguras;
        const columnStyles = {};
        colunas.forEach((c, i) => { columnStyles['k' + i] = { cellWidth: c.width * fatorLargura }; });
        const idxSaldo = colunas.findIndex(c => c.header === 'Saldo');
        columnStyles['k' + idxSaldo] = { ...columnStyles['k' + idxSaldo], halign: 'right' };

        const ordenados = r.slice().sort((a, b) => (parseDataBR(a.dtArquivamento) || 0) - (parseDataBR(b.dtArquivamento) || 0));
        const corpo = ordenados.map(d => {
            const o = {};
            colunas.forEach((c, i) => { o['k' + i] = String(c.get(d) ?? ''); });
            return o;
        });
        const saldoTotal = r.reduce((s, d) => s + (d.saldo || 0), 0);

        doc.autoTable({
            columns: colunas.map((c, i) => ({ header: c.header, dataKey: 'k' + i })),
            body: corpo,
            startY: tabInicioY,
            margin: { left: m, right: m, top: m, bottom: 14 },
            theme: 'grid',
            styles: { font: 'PublicSans', fontSize: 7.5, cellPadding: 1.6, textColor: COR.tintaSec,
                      lineColor: COR.grade, lineWidth: 0.1, overflow: 'linebreak', valign: 'middle' },
            headStyles: { fillColor: COR.azul, textColor: [255, 255, 255], fontStyle: 'bold', fontSize: 8 },
            alternateRowStyles: { fillColor: COR.cartao },
            columnStyles,
            foot: [{ k0: 'TOTAL', k1: '', k2: '', k3: '', [`k${idxSaldo}`]: fmtBRL(saldoTotal) }],
            footStyles: { font: 'PublicSans', fontStyle: 'bold', fontSize: 8, fillColor: COR.azulTint, textColor: COR.tinta, lineColor: COR.grade, lineWidth: 0.1 },
            didParseCell: (data) => {
                if (data.section === 'foot' && data.column.index === idxSaldo) data.cell.styles.halign = 'right';
            },
            didDrawPage: () => desenharRodape(doc, TITULO, carimbo, pw, ph, m),
        });
    }

    function gerarPDF(dados) {
        const doc = novoDocPDF();
        montarResumo(doc, dados);
        if (dados.length) montarTabela(doc, dados);
        const dataArquivo = new Date().toISOString().slice(0, 10);
        doc.save(`processos_arquivados_saldo_projudi_${dataArquivo}.pdf`);
    }

    // ── Botão na tela do relatório ───────────────────────────────────────────────
    function injetarBotao() {
        const form = formularioArquivadosSaldo();
        if (!form) return;
        const buttonBar = document.querySelector('table.buttonBar td.buttons');
        if (!buttonBar || document.getElementById('btn-arqsaldo-extrair')) return;

        const status = document.createElement('span');
        status.id = 'arqsaldo-status';
        status.style.marginRight = '10px';
        status.style.fontSize = '12px';
        status.style.color = '#525252';

        const botao = document.createElement('input');
        botao.type = 'button';
        botao.id = 'btn-arqsaldo-extrair';
        botao.className = 'button';
        botao.value = 'Extrair CSV e Gerar PDF';
        botao.style.marginLeft = '8px';
        botao.onclick = async () => {
            botao.disabled = true;
            status.textContent = 'Solicitando o relatório em CSV...';
            // Marca visualmente o rádio CSV (não é o que dispara a extração — isso é
            // feito via GM_xmlhttpRequest logo abaixo — mas deixa a tela consistente com
            // o que o usuário pediu: "clicar em Arquivo CSV").
            const radioCSV = form.querySelector('input[name="tipoExportacao"][value="CSV"]');
            if (radioCSV && !radioCSV.checked) radioCSV.click();
            try {
                const texto = await coletarCSV(form.action);
                const dados = parseCSV(texto);
                status.textContent = `${dados.length} processo(s) — gerando PDF...`;
                gerarPDF(dados);
                status.textContent = `✓ ${dados.length} processo(s) extraído(s). PDF baixado.`;
            } catch (err) {
                console.error('[Projudi Arquivados c/ Saldo]', err);
                status.textContent = `Erro: ${err.message}`;
                alert(`Não foi possível extrair o relatório:\n\n${err.message}`);
            } finally {
                botao.disabled = false;
            }
        };

        buttonBar.insertBefore(status, buttonBar.firstChild);
        buttonBar.appendChild(botao);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', injetarBotao);
    } else {
        injetarBotao();
    }
})();
